m 146 BCE onwards."}, {"sourceSlug": "posidonius", "sourceName": "Posidonius", "verb": "OCCURS_IN", "targetSlug": "rhodes", "targetName": "Rhodes, Greece", "context": "Posidonius established a renowned philosophical school in Rhodes, where he taught and conducted much of his research and political activities."}, {"sourceSlug": "posidonius", "sourceName": "Posidonius", "verb": "INFLUENCES", "targetSlug": "strabo", "targetName": "Strabo", "context": "Posidonius's geographical works, particularly his detailed descriptions and theories, were a major source and influence for the geographer Strabo."}]}, {"timestamp": "2026-11-25T09:13:14Z", "editorId": "gemini-2.5-flash·cloud·GH#45583030983", "field": "detailsJson.places", "oldValue": [{"name": "Apamea", "role": "Birth place"}], "newValue": [{"name": "Apamea, Syria", "role": "Birthplace"}, {"name": "Rhodes, Greece", "role": "Center of scholarship"}, {"name": "Rome, Italy", "role": "Influenced Roman elite"}]}, {"timestamp": "2026-11-25T09:13:14Z", "editorId": "gemini-2.5-flash·cloud·GH#45583030983", "field": "subjects", "oldValue": ["Journalists & Chroniclers"], "newValue": ["Greece", "Syria", "Stoicism", "Philosophy", "Astronomy", "Geography", "History", "Mathematics", "Roman Republic", "Hellenistic Period"]}, {"timestamp": "2026-11-25T09:13:14Z", "editorId": "gemini-2.5-flash·cloud·GH#45583030983", "field": "frameworks", "oldValue": ["CAUSE_AND_EFFECT", "CULTURAL_DIFFUSION", "TEMPORAL_LINKAGE"], "newValue": ["CULTURAL_TRANSMISSION", "LONGUE_DUREE", "STRUCTURAL_ANALYSIS"]}], "_unsyncedEdits": true}
